"""Build local human review page and immutable artifact inventory."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'reports/art/20261009-far-view'

def main():
 captures=json.loads((OUT/'captures.json').read_text())
 manifest=json.loads((OUT/'manifest.json').read_text())
 files={str(p.relative_to(OUT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.rglob('*') if p.is_file() and p.suffix in ['.png','.mp4'] and 'frames' not in p.parts}
 inventory={'version':'far_view_20261009_v1','human_review':'pending','files':files,'captures':captures}
 (OUT/'inventory.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2)+'\n')
 html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>最远视角 · 舰娘美术评审</title>
<style>*{box-sizing:border-box}body{margin:0;background:#102a38;color:#e6f1f6;font:16px/1.6 system-ui,sans-serif}header,main{max-width:1500px;margin:auto;padding:28px}header{padding-bottom:12px}h1{font-size:30px;margin:0 0 8px}p{margin:8px 0;color:#bbd1da}.tag{color:#ffda83}section{background:#173747;border:1px solid #365464;border-radius:12px;margin:18px 0;padding:20px}button,select,input,textarea{font:inherit;border:1px solid #6d8c9e;border-radius:7px;padding:9px;color:#eaf6ff;background:#23495c}button{cursor:pointer}button.active{background:#e2bc6e;color:#152c38;border-color:#e2bc6e}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:12px 0}.viewport{overflow:auto;background:#0b1e29;border-radius:8px}#shot{display:block;width:100%;max-width:none}.actual #shot{width:auto}label{display:inline-flex;align-items:center;gap:8px}small{color:#abc5cf}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.asset{background:#285265;border-radius:8px;padding:14px;text-align:center}.asset img{height:180px;max-width:100%;object-fit:contain}.asset .rig{height:65px}.samples img{object-fit:contain;margin:12px}.samples{display:flex;align-items:flex-end;justify-content:center;gap:15px}video{display:block;width:100%;max-height:810px}textarea{width:100%;min-height:140px}a{color:#9edcfa}code{font-size:13px;overflow-wrap:anywhere}#status{color:#ffda83}summary{cursor:pointer}@media(max-width:700px){.grid{grid-template-columns:1fr}main,header{padding:12px}}</style>
<header><div class="tag">Tiny Sea War / 2026-10-09 / 候选 v1 · 等待人工审核</div><h1>以最远视角为主战斗画面</h1><p>三个角色、三种尺寸，同场景切换原版与候选。请优先看最远视角的辨识、拥挤和航向，再看近景。</p></header><main>
<section><h2>01 / 同场景比较</h2><div class="controls"><label>场景<select id="scene"><option value="density22">22单位交错压力布局</option><option value="fleet11">L-01真实11舰开局</option><option value="combat3">实际3v3交战16秒</option><option value="near3">近景兼容检查</option></select></label><label>分辨率<select id="resolution"><option value="1080">1920×1080</option><option value="1440">2560×1440</option><option value="2160">3840×2160</option></select></label><label><input type="checkbox" id="native">原始像素显示（可滚动）</label><a id="open" target="_blank">打开原图</a></div>
<div class="controls" id="variants"><button data-h="0">原版</button><button data-h="48">48px</button><button data-h="56" class="active">56px</button><button data-h="64">64px</button></div><p id="caption"></p><div class="viewport" id="viewport"><img id="shot" alt="战斗美术对照画面"></div><small>适应窗口会缩小整张画面；判断最终像素尺度请勾选原始像素显示。高分辨率对照仅提供22单位56px候选，保持相同逻辑取景。</small></section>
<section><h2>02 / 实际交战动态</h2><p>最远视角56px候选，三样本3v3前12秒。真实Tick、公开视野、原有投射物/航空事件；程序补间候选，不代表五态逐帧动画完成。</p><video controls preload="metadata" src="combat_far56.mp4"></video></section>
<section><h2>03 / 角色与拆件</h2><p>人物直立、舰装独立按航向旋转。以下大图用于核对身份；下方48／56／64px人物用于小尺寸比较。</p><div class="grid">ASSET_CARDS</div></section>
<section><h2>04 / 人工意见</h2><p>重点：能否认出角色和舰种；敌我、航向、选中是否清楚；密集处是否遮挡；人物与舰装是否协调。技术检查不决定美术是否采用。</p>
<div class="controls"><label>倾向尺寸<select id="preference"><option>尚未决定</option><option>48px</option><option>56px</option><option>64px</option><option>需要其他尺寸</option></select></label><label>总体意见<select id="verdict"><option>待审核</option><option>方向可继续，需修改</option><option>此版可进入下一轮集成</option><option>方向需重做</option></select></label></div><textarea id="feedback" placeholder="请填写喜欢/不喜欢的具体位置、角色、尺寸与动态问题。"></textarea><div class="controls"><button id="download">下载评审意见 JSON</button><span id="status">意见只保存在本机浏览器，可下载后交回。</span></div></section>
<section><details><summary>范围、限制与复现</summary><p>L-01只替换厌战和雪风，其他角色仍为原版。22单位布局重复三名样本，用于遮挡压力观察，不代表22名角色覆盖，也不是实际侦查或导航证据；HUD仍沿用样本3v3。</p><p>未完成：全量角色迁移、正式五态帧动画、精确炮口绑定、公共VFX远景适配、不同天气/长时性能和真人点选验收。样本VFX挂点暂回到真实单位中心。</p><p>Godot实际试玩入口：F6切换原版/候选，F7切换48/56/64，其他操作同正式战斗。最远视角默认打开，不记录进度。</p><code>godot --path . --script tools/art_review/far_view/launch.gd</code><br><code>godot --path . --script tools/art_review/far_view/launch.gd -- --sample</code><p><a href="validation.md">技术报告</a> · <a href="manifest.json">来源与裁切记录</a> · <a href="inventory.json">文件哈希</a></p></details></section></main>
<script>const inventory=INVENTORY;let height='56';const el=id=>document.getElementById(id);function update(){let scene=el('scene').value,res=el('resolution').value;if(scene!=='density22'){res='1080';el('resolution').value=res}el('resolution').disabled=scene!=='density22';if(res!=='1080'||scene==='near3')height='56';document.querySelectorAll('[data-h]').forEach(b=>{b.disabled=(res!=='1080'||scene==='near3')&&b.dataset.h!=='56';b.classList.toggle('active',b.dataset.h===height)});let file=`${scene}_${res}_${height}.png`;el('shot').src=file;el('open').href=file;el('viewport').classList.toggle('actual',el('native').checked);el('caption').textContent=({density22:'受控22单位交错布局：重复三样本，专门观察遮挡。不是实际战斗或视野证据。',fleet11:'L-01公开开局：只替换厌战/雪风，其他角色保留原版。',combat3:'真实3v3同一16秒战斗状态：只改变表现，规则状态一致。',near3:'近景只检查缩放与构图，不能代替最远视角验收。'}[scene])+` 当前：${height==='0'?'原版':height+'px候选'}`;}
document.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{height=b.dataset.h;update()});['scene','resolution','native'].forEach(id=>el(id).onchange=update);const key='tsw_far_view_20261009_v1';try{const draft=JSON.parse(localStorage.getItem(key)||'{}');['preference','verdict','feedback'].forEach(id=>{if(draft[id])el(id).value=draft[id]})}catch(e){}function payload(){return{version:inventory.version,recorded_at:new Date().toISOString(),preference:el('preference').value,verdict:el('verdict').value,feedback:el('feedback').value,viewed_scene:el('scene').value,viewed_height:height,artifact_sha256:inventory.files}}['preference','verdict','feedback'].forEach(id=>el(id).oninput=()=>{try{localStorage.setItem(key,JSON.stringify(payload()))}catch(e){el('status').textContent='浏览器不允许保存，请下载意见。'}});el('download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload(),null,2)],{type:'application/json'}));a.download='far_view_review_20261009.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);el('status').textContent='已生成下载文件；尚未提交或采用。'};update();</script></html>'''
 cards=[]
 for id,name in [('warspite','厌战'),('yukikaze','雪风'),('enterprise_cv6','企业')]:
  cards.append(f'<div class="asset"><h3>{name}</h3><img src="assets/{id}_body.png" alt="{name}人物"><br><img class="rig" src="assets/{id}_rig.png" alt="{name}独立舰装"><div class="samples">'+''.join(f'<div><img style="height:{h}px" src="assets/{id}_body.png" alt="{h}px"><br><small>{h}px</small></div>' for h in [48,56,64])+'</div></div>')
 html=html.replace('ASSET_CARDS',''.join(cards)).replace('INVENTORY',json.dumps(inventory,ensure_ascii=False))
 (OUT/'review.html').write_text(html)
 print(f'Review built: {len(captures)} stills, {len(files)} hashed media')
if __name__=='__main__':main()
